      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "RabbitMQ Performance Benchmarking for Spring XD Cluster",
      "activity_description": "Set up RabbitMQ benchmark environment, run workload throughput/latency test suites, and compile baseline reference data for Spring XD cluster planning (U1).",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Spring XD Module Documentation and Javadoc Enhancement",
      "activity_description": "Author high-level descriptions and Javadocs for all Spring XD modules (sources, processors, sinks, jobs) to clearly document module purpose and capabilities (U2, U4).",
      "most_likely_effort": 18
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "RPM Publishing Pipeline Setup for Spring.io Repository",
      "activity_description": "Configure release build scripts to package Spring XD as RPMs and publish artifacts to http://repo.spring.io/libs-release-local/ (U3).",
      "most_likely_effort": 12
    },
    {
